import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const raw=p=>fs.readFileSync(path.join(root,p));
const read=p=>{const b=raw(p);return b.toString(b[0]===255&&b[1]===254?'utf16le':'utf8').replace(/^\uFEFF/,'').replaceAll('\r','');};
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
function source(p){const s=JSON.parse(read(p));assert.equal(s.stable_copy_verified,true);assert.equal(s.dependencies_installed,false);assert.equal(s.production_approved,false);assert.equal(sha(Buffer.from(s.files.map(f=>`${f.path}\0${f.sha256}\0${f.size}`).join('\n')+'\n')),s.source_sha256);assert.equal(new Set(s.files.map(f=>f.path)).size,s.files.length);return s;}
const prefix='docs/evidence/d-download-gc-task-mysql-20261020-r2';
const frozen=source(prefix+'-source.json'), native=read(prefix+'-native.txt');
assert.equal(frozen.files.length,1449);
assert.equal(frozen.source_sha256,'9652b0911539277a3a113ec5cf18eee3bb710f654fb53f5eb79a485b65fb22bf');
for(const m of [`FROZEN files=${frozen.files.length} sha256=${frozen.source_sha256}`,'NATIVE_PARALLELISM build=1 gomaxprocs=1','default_vet=yes','FROZEN_UNIT_POSTCHECK pass=yes','FROZEN_POSTCHECK pass=yes','CLEANED snapshot=True','d_admission_native_exit=0'])assert.ok(native.includes(m),m);
assert.equal(read(prefix+'-stderr.txt'),'');
const parse=p=>read(p).trim().split('\n').filter(Boolean).map(l=>JSON.parse(l));
function passes(es){assert.ok(!es.some(e=>['fail','skip','build-fail'].includes(e.Action)));const done=es.filter(e=>e.Test&&e.Action==='pass');assert.deepEqual(es.filter(e=>e.Test&&e.Action==='run').map(e=>e.Package+'/'+e.Test).sort(),done.map(e=>e.Package+'/'+e.Test).sort());return done;}
const seedNames=['TestDDownloadGCTaskMySQLSeed','TestASensitiveDownloadMFAMySQLSeed'];
for(const file of [prefix+'.jsonl',prefix+'-tagged-seed.txt']){const done=passes(parse(file));assert.equal(done.length,13);assert.deepEqual(done.filter(e=>!e.Test.includes('/')).map(e=>e.Test).sort(),seedNames.slice().sort());assert.ok(done.every(e=>seedNames.some(n=>e.Test===n||e.Test.startsWith(n+'/'))));}
const detached=read(prefix+'-detached-seed.txt');assert.equal((detached.match(/^\s*--- PASS:/gm)||[]).length,13);assert.ok(!detached.includes('--- FAIL:'));assert.match(detached.trimEnd(),/PASS$/);
for(const stage of ['tagged-seed','windows-probe','detached-seed','linux-probe','linux-migration']){assert.ok(native.includes(`NATIVE_PROBE stage=${stage} exit=0 actual_mysql=no`));assert.equal(read(prefix+'-'+stage+'-stderr.txt'),'');}
const binaries=[...native.matchAll(/^NATIVE_PROBE_BINARY name=(\S+) sha256=([a-f0-9]{64})$/gm)].map(m=>({name:m[1],sha256:m[2]}));assert.equal(binaries.length,3);
const owner=native.match(/^FROZEN files=\d+ sha256=[a-f0-9]{64} owner=(.+)$/m)[1].trim();assert.equal(path.dirname(owner).toLowerCase(),root.toLowerCase());assert.match(path.basename(owner),/^\.tmp-d-index-cache-[a-f0-9]{32}$/);assert.equal(fs.existsSync(owner),false);
const initialPrefix='docs/evidence/d-download-gc-task-mysql-20261020-r1', initialSource=source(initialPrefix+'-source.json'), initialNative=read(initialPrefix+'-native.txt');
assert.equal(initialSource.source_sha256,'cbf8d98ce3bf3343cee93e50b45665f3ac1748bd9ca4bb2f49909aef87bc0b3c');
const initialPins=new Map(initialSource.files.map(f=>[f.path,f.sha256]));assert.deepEqual(initialSource.files.map(f=>f.path),frozen.files.map(f=>f.path));assert.deepEqual(frozen.files.filter(f=>initialPins.get(f.path)!==f.sha256).map(f=>f.path),['backend/internal/systembackupevidence/download_gc_task_mysql_test.go']);
const initialOwner=initialNative.match(/^FROZEN files=\d+ sha256=[a-f0-9]{64} owner=(.+)$/m)[1].trim();assert.equal(fs.existsSync(initialOwner),false);const initialExit=Number(initialNative.match(/^d_admission_native_exit=(-?\d+)$/m)[1]);

// Existing ordinary Go/dependency/embed inputs are byte-identical. Reuse that
// exact four-package proof; this run is tagged preparation, not a new full run.
const oldPrefix='docs/evidence/d-download-gc-dependencies-20261020-r4';
const old=source(oldPrefix+'-source.json'), oldNative=read(oldPrefix+'-native.txt');
assert.equal(old.source_sha256,'04c9f4e42ba2df4bef2192eed1e70b84d66fd5a64cc8d21723199176d1e939df');
assert.ok(oldNative.includes(`FROZEN files=${old.files.length} sha256=${old.source_sha256}`));
const oldPassed=passes(parse(oldPrefix+'.jsonl'));assert.equal(oldPassed.length,6114);assert.equal(oldPassed.filter(e=>!e.Test.includes('/')).length,737);assert.ok(oldNative.includes('NATIVE_EXIT full_packages=0'));assert.ok(oldNative.includes('FROZEN_UNIT_POSTCHECK pass=yes'));assert.ok(oldNative.includes('FROZEN_POSTCHECK pass=yes'));
const oldPins=new Map(old.files.map(f=>[f.path,f.sha256])), newPins=new Map(frozen.files.map(f=>[f.path,f.sha256]));assert.ok(old.files.every(f=>newPins.has(f.path)));
const changed=frozen.files.filter(f=>oldPins.get(f.path)!==f.sha256).map(f=>f.path).sort();
assert.deepEqual(changed,['backend/internal/systembackupevidence/download_gc_task_mysql_test.go','scripts/system-backup-a-evidence-validation.ps1','scripts/system-backup-d-config-writer-validation.ps1','scripts/system-backup-d-download-admission-native-validation.ps1','scripts/system-backup-d-download-gc-task-dispatch.test.ps1','scripts/system-backup-d-download-gc-task-phase.sh'].sort());
const addedGo=read(changed.find(p=>p.endsWith('.go')));assert.ok(addedGo.startsWith('//go:build systembackup_mysql\n'));assert.ok(!addedGo.includes('t.Parallel('));assert.ok(!addedGo.includes('SET FOREIGN_KEY_CHECKS'));assert.ok(addedGo.includes('component_and_predicate=same'));assert.ok(addedGo.includes('!reflect.DeepEqual(full, f.pruneLocks(t, isolated))'));
const cases=[...addedGo.match(/var dGCTaskMySQLCases = \[\]string\{([\s\S]*?)\n\}/)[1].matchAll(/"([a-z_]+)"/g)].map(m=>m[1]);assert.equal(cases.length,18);assert.equal(new Set(cases).size,18);
const phase=read('scripts/system-backup-d-download-gc-task-phase.sh');assert.equal((phase.match(/-test.run/g)||[]).length,1);assert.ok(phase.includes('^TestDDownloadGCTaskMySQL$'));assert.ok(phase.includes('new_cases=18'));assert.ok(phase.includes('full_gc=not_run'));assert.ok(phase.includes('role_approval=no'));
const staticChecks=[];
for(const version of [5,7]){const file=`docs/evidence/d-download-gc-task-mysql-static-pwsh${version}-20261020.txt`,log=read(file);assert.match(log,new RegExp(`STATIC_RUNTIME powershell=${version}\\.`));assert.ok(log.includes('STATIC_EXIT=0 profiles=8 build=no remote=no dependencies-installed=no'));const checks=[...log.matchAll(/^STATIC_PASS script=(\S+) sha256=([a-f0-9]{64})$/gm)];assert.equal(checks.length,8);assert.equal(new Set(checks.map(m=>m[1])).size,8);for(const m of checks)assert.equal(sha(raw('scripts/'+m[1])),m[2]);staticChecks.push({log:file,sha256:sha(raw(file)),runtime_major:version,dispatch_checks:8});}
const offlinePath='docs/evidence/d-download-gc-task-phase-offline-20261020-r2.txt',offline=read(offlinePath);for(const flag of [0,1])assert.ok(offline.includes(`OFFLINE_PASS gc_task_phase embedded_migration=${flag} argv_pins=yes payload_syntax=yes cleanup_trap=yes actual_mysql=no network=no`));assert.ok(!offline.includes('PASS d-download-gc-task-mysql'));
for(const reason of ['namespace_uid','binary_hash','input_hash','empty_binary'])assert.ok(offline.includes(`OFFLINE_PASS gc_task_phase rejection=${reason} remote_actions=zero actual_mysql=no network=no`));
const currentList='docs/evidence/d-download-gc-task-mysql-current-files-20261020.txt';assert.deepEqual(read(currentList).trim().split('\n'),frozen.files.map(f=>f.path));for(const f of frozen.files){const b=raw(f.path);assert.equal(b.length,f.size,f.path);assert.equal(sha(b),f.sha256,f.path);}
const cleanupPath='docs/evidence/d-download-gc-task-mysql-cleanup-20261020.json',cleanup=JSON.parse(read(cleanupPath));assert.equal(cleanup.dependencies_installed,false);assert.equal(cleanup.remote_run,false);assert.equal(cleanup.paths.length,3);for(const e of cleanup.paths){assert.equal(e.absent,true);assert.equal(fs.existsSync(e.path),false);}for(const owned of [owner,initialOwner])assert.ok(cleanup.paths.some(e=>e.path===owned));
const record={kind:'d_download_gc_task_mysql_preparation_review',recorded_at:new Date().toISOString(),source:{manifest:prefix+'-source.json',sha256:frozen.source_sha256,files:frozen.files.length,manifest_sha256:sha(raw(prefix+'-source.json'))},native:{transcript:prefix+'-native.txt',sha256:sha(raw(prefix+'-native.txt')),exit:0,default_vet:true,parallelism:1,initial_seed_checks:13,tagged_seed_checks:13,detached_seed_checks:13,source_postchecks:true,binaries},changed_since_ordinary_proof:changed,ordinary_proof:{prefix:oldPrefix,source_sha256:old.source_sha256,jsonl_sha256:sha(raw(oldPrefix+'.jsonl')),main:737,all:6114,ordinary_go_dependency_and_embed_inputs_unchanged:true,repeated:false,current_single_full_run_claimed:false},static_checks:staticChecks,offline_phase:{log:offlinePath,sha256:sha(raw(offlinePath)),driver_sha256:sha(raw('docs/evidence/d-download-gc-task-phase-offline-20261020.sh')),branches:2,network:false,actual_mysql:false,initial_bash_launch:'Sandbox Win32 error 5 prevented signal-pipe creation; read-only syntax and stubbed phase checks subsequently passed outside the sandbox.'},case_names:cases,actual_mysql_cases:0,remote_run:false,dependencies_installed:false,production_approved:false,full_gc_run:false,role_approved:false,cleanup:cleanupPath,current_input_list:currentList,current_pinned_sources_match:true,scope:'Offline preparation of eighteen actual-MySQL task-eligibility component cases. Scope IDs are synthetic. Actual MySQL execution/plans/locking, complete collector, restricted role, global lock order, physical capacity and original six scopes remain unproved.'};
record.initial_prototype={prefix:initialPrefix,source_sha256:initialSource.source_sha256,manifest_sha256:sha(raw(initialPrefix+'-source.json')),native_sha256:sha(raw(initialPrefix+'-native.txt')),exit:initialExit,source_postchecks:initialNative.includes('FROZEN_POSTCHECK pass=yes'),owner_absent:true,superseded_by:'Final source adds independent prune predicate/component lock-footprint equivalence, avoiding backup-FK wait false positives. No initial-prototype result is expanded to the final source.'};
record.offline_phase.negative_cases=4;
record.artifacts=fs.readdirSync(path.join(root,'docs/evidence')).filter(n=>[path.basename(initialPrefix),path.basename(prefix)].some(stem=>n.startsWith(stem+'.')||n.startsWith(stem+'-'))).sort().map(n=>({path:'docs/evidence/'+n,sha256:sha(raw('docs/evidence/'+n))}));
record.cleanup_sha256=sha(raw(cleanupPath));
record.current_input_list_sha256=sha(raw(currentList));
const out=path.join(root,'docs/evidence/d-download-gc-task-mysql-preparation-accepted-20261020.json');if(process.argv.includes('--check')){const saved=JSON.parse(fs.readFileSync(out,'utf8'));record.recorded_at=saved.recorded_at;assert.deepEqual(record,saved);}else{assert.equal(fs.existsSync(out),false);fs.writeFileSync(out,JSON.stringify(record,null,2)+'\n',{flag:'wx'});}
console.log(JSON.stringify({source:record.source,seed_checks:13,detached_checks:13,ordinary_proof_repeated:false,static_checks:16,offline_phase_branches:2,actual_mysql_cases:0,remote_run:false,cleaned_directories:cleanup.paths.length}));
